WITH folds AS (SELECT held_out_circuit, target, model, count(*) AS n, avg(abs(predicted-actual)) AS mae FROM read_csv_auto('data/processed/experimental/four_circuit_response_candidates_v2/strict_predictions.csv') GROUP BY ALL) SELECT target, model, avg(mae) AS macro_mae, cast(sum(n) AS integer) AS test_passages, count(*) AS circuit_count FROM folds GROUP BY ALL ORDER BY target,model;
